# -*- coding: utf-8 -*-
"""Local report, blinded multi-relevant top-five review and inspection artifacts."""
import base64,html,json,sys,random
from pathlib import Path
from collections import Counter
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
import numpy as np
from research.sticker_encoder.weak_model import digest,save

def main():
 out=ROOT/'outputs/sticker-semantic-v3-local-20261118';source=ROOT/'outputs/sticker-codex-local-20261118'
 data=json.loads((out/'full-dataset.json').read_text());rows=data['rows'];ids=[r['id'] for r in rows]
 feats=dict(np.load(out/'evaluation-features.npz'));feats['v2_image']=np.load(out/'v2-evaluation-features.npz')['v2_image'];report=json.loads((out/'evaluation-report.json').read_text());training=json.loads((out/'training-report.json').read_text())
 previous=json.loads((out/'v2-comparison.json').read_text())
 for group,g in report['metrics'].items():g['v2']=previous['metrics'][group]
 if list(feats['ids'])!=ids:raise ValueError('Feature IDs')
 # Exclude detected near-duplicates in both retrieval systems using fixed identity code.
 import sticker_identity
 fps=[sticker_identity.fingerprint(base64.b64encode((source/r['image']).read_bytes()).decode()) for r in rows]
 coarse=np.array([list(f['coarse']) for f in fps],dtype=np.float32);queries=[i for i,r in enumerate(rows) if r['split']=='test'];rng=random.Random(20261118);pairs={};rankings={};display=[];duplicates=[]
 stylefile=np.load(out/'all-style-features.npz')
 if list(stylefile['ids'])!=ids:raise ValueError('Style IDs')
 style_distance=1-stylefile['style']@stylefile['style'].T
 matrices={m:feats[m+'_image']@feats[m+'_image'].T for m in ['v2','v3']}
 for i in queries:
  excluded={i}
  for j in np.flatnonzero(np.mean(np.abs(coarse-coarse[i]),axis=1)<=8):
   if i!=j and sticker_identity.same_image(fps[i],fps[j]):excluded.add(int(j));duplicates.append([ids[i],ids[j]])
  union=set();ranking={}
  for m,matrix in matrices.items():
   order=[int(j) for j in np.argsort(-matrix[i],kind='stable') if int(j) not in excluded][:5];ranking[m]=[]
   for rank,j in enumerate(order,1):
    key=ids[i]+'__'+ids[j];union.add(j);ranking[m].append(key)
    pairs.setdefault(key,{'query_id':ids[i],'candidate_id':ids[j],'query_split':'fresh_test' if ids[i].startswith('E') else 'old_test','style_distance':float(style_distance[i,j]),'models':{}})['models'][m]={'rank':rank,'semantic_cosine':float(matrix[i,j])}
  rankings[ids[i]]=ranking
  candidates=sorted(union);rng.shuffle(candidates)
  display.append({'query':ids[i],'split':'新测试图' if ids[i].startswith('E') else '旧测试图','candidates':[{'id':ids[j],'key':ids[i]+'__'+ids[j]} for j in candidates]})
 public={'queries':display,'revision':digest(out/'checkpoint-lock.json'),'image_base':'../sticker-codex-local-20261118/images/'}
 save(out/'top5-researcher-key.json',{'pairs':pairs,'rankings':rankings,'near_duplicate_exclusions':duplicates,'dataset_sha256':digest(out/'full-dataset.json'),'policy':'Query-wise pooled v2/v3 top5; unknown relevance is not negative. Test queries never trained; gallery may contain train/validation images, as declared retrieval task.'})
 save(out/'top5-review-data.json',public)
 style_orders={q:{m:sorted(keys,key=lambda k:-pairs[k]['style_distance']) for m,keys in ranked.items()} for q,ranked in rankings.items()}
 save(out/'top5-style-order.json',{'rankings':style_orders,'policy':'Within retrieved top5 candidates only; same meaning NOT confirmed until review. Do not present as qualified divergence output. Higher1-cos(ALADIN) is more visually distant; no perceptual validation.'})
 template='''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>前五名同义候选核对</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f5f3;color:#233d38;font:16px system-ui;line-height:1.6}main{max-width:1100px;margin:auto;padding:28px}h1{margin:0}header,.query,.card,.tools{background:white;padding:20px;border-radius:16px;margin-bottom:18px}small{color:#5f716b}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.query{display:flex;align-items:center;gap:24px}.query img{width:150px;height:150px;object-fit:contain}.card img{width:100%;height:180px;object-fit:contain}select,input,button{font:inherit;padding:9px;border:1px solid #b9ccc2;border-radius:8px;max-width:100%}button{background:#245c4c;color:white;cursor:pointer}.card select{width:100%;margin-top:8px}.card textarea{width:100%;min-height:56px;border:1px solid #b9ccc2;border-radius:8px;margin-top:8px}.tools{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.muted{color:#65716e}.notice{padding:12px;background:#eef3ef;border-radius:8px}#status{min-height:28px}a{color:#245c4c}@media(max-width:650px){main{padding:14px}.grid{grid-template-columns:1fr 1fr;gap:8px}.card{padding:12px}.card img{height:140px}.query img{width:100px;height:100px}.query{gap:12px}h1{font-size:25px}}</style><main><header><h1>前五名候选 · 同义核对</h1><p>每张查询图展示两版算法前五名的混合候选。顺序已打乱、分数已隐藏，可以有多张正确答案。</p><div class="notice">判断是否可在同一常见聊天语境中替换，且保留说话者、对象、否定和核心意图。仅“都开心”“都委屈”不一定同义。无法确定请选“不确定”，不要猜测用户私人含义。</div><p><a href="本地训练与验证报告.html">查看训练报告</a> · 进度保存在本机浏览器；请导出备份。没有人工作答前，不报告人工准确率。</p></header><div class="tools"><label>评分者 <input id="rater" placeholder="填写匿名编号"></label><label>性质 <select id="kind"><option value="">请选择</option><option value="human">本人逐图人工核对</option><option value="ai">AI辅助核对</option></select></label><button id="export">导出评分</button><label>恢复 <input id="import" type="file" accept=".json"></label></div><div class="tools"><button id="prev">上一张</button><select id="querySelect"></select><button id="next">下一张</button><span id="count"></span></div><div id="status" role="status"></div><section id="view"></section></main><script>const D=__DATA__;const key='xiaoyu-top5-'+D.revision;let state={ratings:{},rater:'',kind:'',index:0};try{const s=JSON.parse(localStorage.getItem(key));if(s&&s.ratings)state={...state,...s}}catch{};const $=s=>document.querySelector(s);function persist(){try{localStorage.setItem(key,JSON.stringify(state));$('#status').textContent='已保存到本机；已判断 '+Object.values(state.ratings).filter(x=>x.meaning).length+' 对'}catch{$('#status').textContent='本机存储不可用，请及时导出评分'}};$('#rater').value=state.rater;$('#kind').value=state.kind;$('#rater').oninput=e=>{state.rater=e.target.value;persist()};$('#kind').onchange=e=>{state.kind=e.target.value;persist()};D.queries.forEach((q,i)=>{const o=document.createElement('option');o.value=i;o.textContent=(i+1)+' · '+q.query+' · '+q.split;$('#querySelect').append(o)});function render(){state.index=Math.max(0,Math.min(D.queries.length-1,state.index));const q=D.queries[state.index];$('#querySelect').value=state.index;$('#count').textContent=(state.index+1)+' / '+D.queries.length;$('#view').replaceChildren();const head=document.createElement('div');head.className='query';const img=document.createElement('img');img.src=D.image_base+q.query+'.png';img.alt='查询图 '+q.query;const text=document.createElement('div');const h=document.createElement('h2');h.textContent='查询图 '+q.query;text.append(h);const p=document.createElement('p');p.textContent='以下哪些图能够保留这张图的主要聊天含义？';text.append(p);head.append(img,text);$('#view').append(head);const grid=document.createElement('div');grid.className='grid';q.candidates.forEach(c=>{const card=document.createElement('article');card.className='card';const im=document.createElement('img');im.src=D.image_base+c.id+'.png';im.alt='候选图 '+c.id;card.append(im);const label=document.createElement('small');label.textContent=c.id;card.append(label);const saved=state.ratings[c.key]||{};function select(name,choices){const el=document.createElement('select');el.setAttribute('aria-label',c.id+' '+name);choices.forEach(([value,txt])=>{const op=document.createElement('option');op.value=value;op.textContent=txt;el.append(op)});el.value=saved[name]||'';el.onchange=()=>{state.ratings[c.key]={...(state.ratings[c.key]||{}),[name]:el.value};persist()};card.append(el)}select('meaning',[['','是否同义：尚未判断'],['yes','同义／可替换'],['no','不同义／仅相关'],['uncertain','不确定／缺少语境']]);select('style',[['','视觉风格差异：未评分'],['1','1 · 很相似'],['2','2 · 较相似'],['3','3 · 中等'],['4','4 · 较不同'],['5','5 · 很不同']]);const note=document.createElement('textarea');note.placeholder='依据或疑点（可空）';note.value=saved.notes||'';note.oninput=()=>{state.ratings[c.key]={...(state.ratings[c.key]||{}),notes:note.value};persist()};card.append(note);grid.append(card)});$('#view').append(grid);persist()};$('#prev').onclick=()=>{state.index--;render()};$('#next').onclick=()=>{state.index++;render()};$('#querySelect').onchange=e=>{state.index=Number(e.target.value);render()};$('#export').onclick=()=>{if(!state.rater.trim()||!state.kind){$('#status').textContent='请填写评分者编号，并选择人工或AI辅助核对。';return}const value={schema:'xiaoyu-top5-review-v1',revision:D.revision,exported_at:new Date().toISOString(),rater_id:state.rater,rater_type:state.kind,ratings:state.ratings};const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='top5-ratings.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('#import').onchange=async e=>{try{const value=JSON.parse(await e.target.files[0].text());if(value.revision!==D.revision||!value.ratings)throw Error('不是本轮评分文件');const allowed=new Set(D.queries.flatMap(q=>q.candidates.map(c=>c.key)));for(const[k,v]of Object.entries(value.ratings)){if(!allowed.has(k)||!['','yes','no','uncertain',undefined].includes(v.meaning))throw Error('评分内容无效')}state.ratings=value.ratings;state.rater=value.rater_id||'';state.kind=value.rater_type||'';$('#rater').value=state.rater;$('#kind').value=state.kind;render()}catch(err){$('#status').textContent='恢复失败：'+err.message}};render();</script></html>'''
 (out/'前五名同义核对.html').write_text(template.replace('__DATA__',json.dumps(public,ensure_ascii=False).replace('</','<\\/')))
 def pc(v):return f'{v*100:.1f}%'
 table=''
 for name,label in [('train_eligible','训练图（815）'),('validation_eligible','验证图（123）'),('old_test_all75','旧测试图（75）'),('fresh_test_all75','新测试图（75）'),('fresh_test_clear','新测试：含义明确子集')]:
  g=report['metrics'][name]
  for m in ['v2','v3']:
   x=g[m]['common1250'];table+=f'<tr><td>{label}</td><td>{m}</td><td>{x["n"]}</td><td>{pc(x["recall_at_1"])}</td><td>{pc(x["recall_at_5"])}</td><td>{x["mrr"]:.3f}</td></tr>'
 trainpairs=json.loads((source/'pair-review.json').read_text());labeldata=json.loads((source/'dataset.json').read_text()); selected=training['selected'];fresh=report['metrics']['fresh_test_all75'];q=report['test_label_quality']
 within=''.join(f'<tr><td>{m}</td><td>{pc(fresh[m]["within_subset"]["image_to_caption"]["recall_at_1"])}</td><td>{pc(fresh[m]["within_subset"]["image_to_caption"]["recall_at_5"])}</td><td>{fresh[m]["within_subset"]["image_to_caption"]["mrr"]:.3f}</td></tr>' for m in ['v2','v3'])
 def uncertainty_item(name,d):
  if name=='mrr':return f'<li>MRR：变化 {d["delta"]:+.3f}；来源包重采样 95% 区间 [{d["pack_bootstrap95"][0]:+.3f}, {d["pack_bootstrap95"][1]:+.3f}]。</li>'
  return f'<li>{name}：变化 {d["delta"]*100:+.2f} 个百分点；来源包重采样 95% 区间 [{d["pack_bootstrap95"][0]*100:+.2f}, {d["pack_bootstrap95"][1]*100:+.2f}]。</li>'
 uncertainty=''.join(uncertainty_item(name,d) for name,d in previous['fresh75_v3_minus_v2'].items())
 oldtable=''.join(f'<tr><td>{m}</td><td>{pc(x["recall_at_1"])}</td><td>{pc(x["recall_at_5"])}</td><td>{x["mrr"]:.3f}</td></tr>' for m,x in previous['old_test_common500'].items())

 doc=f'''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>小屿 · 本地算法训练验证</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#f2f4f1;color:#243f37;font:16px system-ui;line-height:1.75}}main{{max-width:1100px;margin:auto;padding:30px}}section{{background:white;padding:26px;border-radius:18px;margin-bottom:22px}}h1{{font-size:32px;margin:0}}h2{{font-size:22px}}a{{color:#19634e}}.tag{{display:inline-block;background:#dfeee6;padding:4px 12px;border-radius:20px}}.scroll{{overflow:auto}}table{{border-collapse:collapse;width:100%;min-width:580px}}td,th{{border-bottom:1px solid #dce5df;text-align:left;padding:10px}}.big{{font-size:23px;font-weight:650}}.note{{color:#63746b}}@media(max-width:600px){{main{{padding:14px}}section{{padding:18px}}h1{{font-size:27px}}}}</style><main><section><span class="tag">2026-11-18 · 本机实验 · 新增付费 API 调用 0 次</span><h1>小屿表情包：训练与验证</h1><p><a href="本地检索测试.html">打开两阶段检索测试 →</a></p><p>新增素材由 Codex 直接看图标注，训练运行在本机 Apple MPS。保留原有 500 张历史机器标签；本轮没有调用方舟，没有改动正式被试图库或线上聊天模型。</p><p class="big">1250 张素材 · 815 张实际训练 · 123 张模型选择 · 75 张新测试</p><p>600 张新增训练图中 465 张含义明确、135 张暂不确定；75 张新增验证图中 48 张明确、27 张暂不确定。加上原有训练 350、验证 75，得到上述训练和选择样本量。新测试 75 张：明确 {q['clear']}、不确定 {q['uncertain']}。另保留旧测试 75 张作次要比较。</p></section><section><h2>这次改了什么</h2><ol><li>标注保留说话者、对象、否定及交际意图，不把看起来开心一律视作同义。</li><li>人工评分入口允许前五张中有多个正确答案；未判断与不确定不算错误。</li><li>从训练集挖掘图片对，经 Codex AI 复核保留 21 对同义跨画风正例、50 对同画风不同义负例；剔除 29 对不可靠候选。</li><li>预先固定两个训练分支：仅描述对比学习、描述加图片对损失；只用验证集选择，之后锁定权重，再查看和评分新测试。</li></ol><p>最终选择：分支 {selected['trial']}、第 {selected['epoch']} 轮、图片对损失权重 {selected['weight']}。训练耗时 {training['seconds']/60:.1f} 分钟。选择包含旧模型的第 0 轮，避免被迫接受更差模型。</p><p class="note">全部新标签与图片对判断均为 AI 弱标签，不是人工金标准。原始 GSE 未被宣称复现；这是自研 Chinese-CLIP 微调实验。ALADIN-ViT 保持作者权重，用于画风距离。</p></section><section><h2>统一 1250 候选描述的检索结果</h2><p>所有集合使用同一候选规模。R@1 / R@5 表示原配描述排进前 1 / 5 名的比例；它们不是“前五张图片同义准确率”。</p><div class="scroll"><table><thead><tr><th>查询集合</th><th>模型</th><th>查询数</th><th>R@1</th><th>R@5</th><th>MRR</th></tr></thead><tbody>{table}</tbody></table></div><p class="note">不应把本表 1250 候选结果与上一轮 500 候选结果直接比较。新测试含义明确子集仅为描述性补充，完整 75 张结果仍保留。</p></section><section><h2>沿用上轮口径：旧测试 75 图、500 候选</h2><div class="scroll"><table><thead><tr><th>模型</th><th>R@1</th><th>R@5</th><th>MRR</th></tr></thead><tbody>{oldtable}</tbody></table></div><p>用于与此前14.7%／30.7%直接对照；这批旧测试已被查看过，不是新的盲测。</p></section><section><h2>新测试内部 75 候选比较</h2><div class="scroll"><table><thead><tr><th>模型</th><th>R@1</th><th>R@5</th><th>MRR</th></tr></thead><tbody>{within}</tbody></table></div><h2>相对上一版 v2 的新测试变化与不确定性</h2><p>v2 为之前测试的模型，v3 为本轮选定模型。以下变化使用统一 1250 候选；对新测试来源包做 5000 次成对自助重采样。</p><ul>{uncertainty}</ul><p>区间包含 0 时，当前样本不足以证明提升稳定。新测试来自已隔离的来源包，仍不是外部全新来源验证。没有依据测试成绩再训练或调参数。</p></section><section><h2>直接核对你关心的前五张图片</h2><p><a href="前五名同义核对.html">打开图片核对页 →</a></p><p>共 150 张查询图、{len(pairs)} 对去重候选。两版模型的候选混排，隐藏分数；逐对记录同义、不同义或不确定，并可记录视觉风格差异。评分可保存和导出。已排除 {len(duplicates)} 个检测到的近重复检索结果。</p><p>只有完成评分后才计算 P@5、Hit@5 及未判定范围。未穷尽整个图库的同义项，不能把它叫作真正的 Recall@5。视觉差异大小也不能单独证明用户感知到了沟通趋异。</p></section><section><h2>可追溯文件</h2><p><a href="evaluation-report.json">完整评估数据</a> · <a href="protocol.json">固定训练方案</a> · <a href="checkpoint-lock.json">模型锁定记录</a> · <a href="pair-review.json">图片对复核</a> · <a href="../sticker-codex-local-20261118/annotations/">逐图标签</a></p><p>实际语义仍需结合聊天语境。本实验衡量公开表情包的一般检索能力，不能替代真实被试对个人表情含义的解释。</p></section></main></html>'''
 review_path=out/'ai-review/summary.json'
 if review_path.exists():
  ai=json.loads(review_path.read_text()); ai_table=''
  for m,d in ai['metrics'].items():
   lo,hi=d['precision_at_5_all_query_bounds']; hl,hu=d['hit_at_5_all_query_bounds']
   ai_table+=f'<tr><td>{m}</td><td>{pc(lo)}–{pc(hi)}</td><td>{pc(hl)}–{pc(hu)}</td><td>{d["fully_judged_queries"]} / 20</td></tr>'
  ai_section=f'''<section><h2>真正的图片候选：20 张随机新测试图的 AI 核对</h2><p>对新测试图预先按随机种子抽取20张，混排两版前五名后由Codex看图复核，共{ai['unique_pairs_reviewed']}对候选。模型名和分数隐藏。不同于上面的原配描述排名，这里直接检查图片的聊天意图是否可替换。</p><div class="scroll"><table><thead><tr><th>模型</th><th>前五名同义比例 P@5 范围</th><th>至少一张同义 Hit@5 范围</th><th>五张均可判定的查询</th></tr></thead><tbody>{ai_table}</tbody></table></div><p>范围下限只计算明确同义，上限假设所有不确定项都同义；这不是置信区间。新模型100个候选位中明确同义12个、不确定17个，所以不能把32.0%的原配描述R@5写成图片同义准确率。</p><p><strong>当前仍不适合作为自动“同义＋趋异”选图的可靠依据。</strong>典型错误是同一人物、同一影视模板压过文字和意图。E0211的“吃老娘一巴掌”返回同一人物的喂食、迟疑等图片；E0215则找到了饮茶提醒，E0436也找到了同一表达但画风不同的图片。各例均保留在核对材料中。</p><p>这只是单一AI评分者的小样本诊断，且训练标签也由同一AI系统生成，不能替代独立人工验证。当前模型已锁定，没有利用这些测试判断重新训练。后续改动需要新的验证流程，当前测试不再充当未见测试。</p><p><a href="ai-review/summary.json">AI核对汇总</a> · <a href="ai-review/ratings.json">逐对判断</a> · <a href="ai-review/E0211.jpg">错误样例</a> · <a href="ai-review/E0215.jpg">饮茶样例</a> · <a href="ai-review/E0436.jpg">跨风格样例</a></p></section>'''
  doc=doc.replace('<section><h2>直接核对你关心的前五张图片</h2>',ai_section+'<section><h2>直接核对你关心的前五张图片</h2>')
 (out/'本地训练与验证报告.html').write_text(doc)
 save(out/'review-readiness.json',{'queries':len(display),'pairs':len(pairs),'human_ratings':0,'near_duplicate_exclusions':len(duplicates),'report_sha256':digest(out/'本地训练与验证报告.html')})
 print(json.dumps({'queries':len(display),'pairs':len(pairs),'near_duplicate_exclusions':len(duplicates)}))
